import net.minecraft.world.item.component.*;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.Blocks;
/** Native health/healing/wear and real edited blocks; inventory probes never mutate container contents. */
public final class RadiationSmoke {
 static int next=300;
 static Player player(ServerLevel l){return new Player(l,new com.mojang.authlib.GameProfile(new UUID(0,next++),"RadiationProbe")){@Override public GameType gameMode(){return GameType.SURVIVAL;}};}
 static void equip(Player p,String material)throws Exception{String[] names={"helmet","chestplate","leggings","boots"};for(int i=0;i<4;i++)p.setItemSlot(Radiation.ARMOR[i],new ItemStack(net.minecraft.core.registries.BuiltInRegistries.ITEM.getValue(net.minecraft.resources.Identifier.parse(material+"_"+names[i]))));update(p);}
 static void update(LivingEntity e)throws Exception{var m=LivingEntity.class.getDeclaredMethod("detectEquipmentUpdates");m.setAccessible(true);m.invoke(e);}
 static ItemStack shulker(ItemStack item){var box=new ItemStack(Items.SHULKER_BOX);box.set(DataComponents.CONTAINER,ItemContainerContents.fromItems(List.of(item)));return box;}
 static void require(boolean value,String message){if(!value)throw new AssertionError(message);}
 public static void verify(ServerLevel l)throws Exception{
  var effect=UraniumContent.RADIATION.value();
  for(int pieces=0;pieces<=4;pieces++){var p=player(l);equip(p,"minecraft:iron");for(int i=0;i<pieces;i++){var n=new String[]{"helmet","chestplate","leggings","boots"}[i];var material=i%2==0?"diamond":"netherite";p.setItemSlot(Radiation.ARMOR[i],new ItemStack(net.minecraft.core.registries.BuiltInRegistries.ITEM.getValue(net.minecraft.resources.Identifier.withDefaultNamespace(material+"_"+n))));}update(p);p.setHealth(20);boolean applied=effect.applyEffectTick(l,p,0);require(Radiation.unprotectedPieces(p)==4-pieces&&Math.abs(p.getHealth()-(20-.5F*(4-pieces)))<1e-5,"proportional native material shielding pieces="+pieces+" health="+p.getHealth());for(var slot:Radiation.ARMOR)require(p.getItemBySlot(slot).getDamageValue()==0,"iron/diamond/netherite radiation wear immunity");require(applied==(pieces<4),"full shielding ends active effect");}
  for(var material:List.of("minecraft:leather","minecraft:copper","minecraft:chainmail","minecraft:golden","blockbranch:bronze")){var p=player(l);equip(p,material);effect.applyEffectTick(l,p,0);for(var slot:Radiation.ARMOR)require(p.getItemBySlot(slot).getDamageValue()==1,"fragile native wear "+material);}
  for(var material:List.of("blockbranch:silver","blockbranch:steel","blockbranch:stainless_steel","blockbranch:titanium_alloy","blockbranch:platinum_alloy")){var p=player(l);equip(p,material);effect.applyEffectTick(l,p,0);require(Math.abs(p.getHealth()-18)<1e-5,"iron-level alloy does not shield "+material);for(var slot:Radiation.ARMOR)require(p.getItemBySlot(slot).getDamageValue()==0,"iron-level alloy has no radiation wear "+material);}
  var healing=player(l);healing.setHealth(10);healing.heal(4);require(healing.getHealth()==14,"ordinary healing unchanged");healing.setHealth(10);healing.addEffect(new MobEffectInstance(UraniumContent.RADIATION,100));healing.heal(4);require(healing.getHealth()==12,"active radiation halves native healing");equip(healing,"minecraft:diamond");Radiation.tick(healing);require(!healing.hasEffect(UraniumContent.RADIATION),"complete material set removes exposure/effect");healing.setHealth(10);healing.heal(4);require(healing.getHealth()==14,"healing restored after radiation removal");
  for(var item:List.of(UraniumContent.ORE.asItem(),UraniumContent.DEEPSLATE_ORE.asItem(),UraniumContent.RAW,UraniumContent.INGOT,UraniumContent.TIP,UraniumContent.SWORD,UraniumContent.AXE,UraniumContent.SPEAR)){var raw=new ItemStack(item);require(Radiation.radioactive(raw),"all uranium forms expose");var box=shulker(raw);var before=box.copy();require(!Radiation.radioactive(box)&&ItemStack.isSameItemSameComponents(before,box),"shulker shields without mutation");}
  var raw=new ItemStack(UraniumContent.RAW);var bundle=new ItemStack(Items.BUNDLE);bundle.set(DataComponents.BUNDLE_CONTENTS,BundleContents.EMPTY.copyWithContents(java.util.stream.Stream.of(raw.copy())));require(raw.getCount()==1&&bundle.get(DataComponents.BUNDLE_CONTENTS).size()==1&&Radiation.radioactive(bundle),"filled bundle does not shield and fixture retains original raw stack");var nested=new ItemStack(Items.CHEST);nested.set(DataComponents.CONTAINER,ItemContainerContents.fromItems(List.of(shulker(raw))));require(!Radiation.radioactive(nested),"nested shulker remains shielding boundary");var chest=new ItemStack(Items.CHEST);chest.set(DataComponents.CONTAINER,ItemContainerContents.fromItems(List.of(raw)));require(Radiation.radioactive(chest),"ordinary container item does not shield");
  var clean=new ItemStack(Items.PAPER);var hot=new ItemStack(UraniumContent.RAW);for(int i=0;i<14;i++){var c=new ItemStack(Items.CHEST);c.set(DataComponents.CONTAINER,ItemContainerContents.fromItems(List.of(clean,clean)));clean=c;var h=new ItemStack(Items.CHEST);h.set(DataComponents.CONTAINER,ItemContainerContents.fromItems(List.of(hot,hot)));hot=h;}require(!Radiation.radioactive(clean)&&Radiation.radioactive(hot),"large shared container trees require actual uranium, never a scan-budget phantom source");
  var carrier=player(l);carrier.getInventory().setItem(0,shulker(raw));require(!Radiation.carried(carrier),"carried shulker shielding");carrier.setItemSlot(EquipmentSlot.OFFHAND,raw);require(Radiation.carried(carrier),"direct offhand source bypasses unrelated shulker");carrier.tickCount=Math.floorMod(-carrier.getId(),20);Radiation.tick(carrier);require(carrier.hasEffect(UraniumContent.RADIATION),"inventory exposure applies native status");
  var profile=new com.mojang.authlib.GameProfile(new UUID(0,981),"UraniumMenuProbe");var menuPlayer=new net.minecraft.server.level.ServerPlayer(l.getServer(),l,profile,net.minecraft.server.level.ClientInformation.createDefault());menuPlayer.connection=new net.minecraft.server.network.ServerGamePacketListenerImpl(l.getServer(),new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND),menuPlayer,net.minecraft.server.network.CommonListenerCookie.createInitial(profile,false));menuPlayer.getAdvancements();menuPlayer.getInventory().setItem(0,shulker(raw));require(!Radiation.carried(menuPlayer),"menu baseline shielded");menuPlayer.containerMenu.setCarried(raw.copy());require(Radiation.carried(menuPlayer),"cursor is carried uranium");menuPlayer.containerMenu.setCarried(ItemStack.EMPTY);var crafting=menuPlayer.inventoryMenu.getCraftSlots();crafting.setItem(0,raw.copy());require(Radiation.carried(menuPlayer),"personal crafting inputs are carried uranium");crafting.setItem(0,ItemStack.EMPTY);require(!Radiation.carried(menuPlayer),"empty cursor/crafting do not invent source");var storage=new net.minecraft.world.SimpleContainer(27);storage.setItem(0,raw.copy());menuPlayer.containerMenu=net.minecraft.world.inventory.ChestMenu.threeRows(9,menuPlayer.getInventory(),storage);require(!Radiation.carried(menuPlayer),"open world chest slots are not player-carried inventory");
  var center=new BlockPos(592,64,0);l.getChunkAt(center);for(int y=60;y<=68;y++)for(int z=-4;z<=4;z++)for(int x=588;x<=596;x++)if(l.getBlockState(new BlockPos(x,y,z)).is(UraniumContent.ORE)||l.getBlockState(new BlockPos(x,y,z)).is(UraniumContent.DEEPSLATE_ORE))l.setBlock(new BlockPos(x,y,z),Blocks.AIR.defaultBlockState(),2);require(!Radiation.nearby(l,center),"no invented world source");var source=center.offset(2,0,0);l.setBlock(source,UraniumContent.ORE.defaultBlockState(),2);require(Radiation.nearby(l,center),"edited ore outside natural band exposes");l.setBlock(source,Blocks.AIR.defaultBlockState(),2);require(!Radiation.nearby(l,center),"mining/removing source respects edits");var far=new BlockPos(1000000,64,1000000);require(l.getChunkSource().getChunkNow(far.getX()>>4,far.getZ()>>4)==null&&!Radiation.nearby(l,far)&&l.getChunkSource().getChunkNow(far.getX()>>4,far.getZ()>>4)==null,"exposure does not force unloaded chunks");
  blockbranch.Blockbranch.LOGGER.info("URANIUM native radiation partial/full armor, fragile wear, healing, shulker/bundle and edited/loaded-only sources passed");
 }
 private RadiationSmoke(){}
}
